def download(url: str, dest: Path) -> bool:
    if dest.exists():
        print(f"  = {dest.name} (já baixado)")
        return True
    try:
        with urllib.request.urlopen(url, timeout=180) as r:
            dest.write_bytes(r.read())
        print(f"  ok {dest.name} ({dest.stat().st_size // 1024} KB)")
        return True
    except Exception as e:  # noqa: BLE001 — uma falha não interrompe as demais
        print(f"  x {dest.name}: {e}")
        return False


def main() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    jobs = [(BASE + p, OUT / f"{n}.png") for n, p in ASSETS.items()]
    jobs += [(VIDEO_BASE + p, OUT / f"{n}.mp4") for n, p in VIDEOS.items()]
    ok = sum(download(url, dest) for url, dest in jobs)
    print(f"Pronto: {ok}/{len(jobs)} em {OUT}")
    return 0 if ok == len(jobs) else 1


if __name__ == "__main__":
    sys.exit(main())
